import os,re,collections
root="AlgebraicJacobian"
files={}
for dp,dn,fn in os.walk(root):
    for f in fn:
        if f.endswith(".lean"):
            p=os.path.join(dp,f)
            mod=p[:-5].replace("/",".")
            files[mod]=p
files["AlgebraicJacobian"]="AlgebraicJacobian.lean"
print("total modules on disk:",len(files))
imports={}
for m,p in files.items():
    s=open(p).read()
    imps=re.findall(r'^import\s+([A-Za-z0-9_.]+)',s,re.M)
    imports[m]=[i for i in imps]
# dangling: imports of AlgebraicJacobian.* that don't exist
dangling=[]
for m,imps in imports.items():
    for i in imps:
        if i.startswith("AlgebraicJacobian") and i not in files:
            dangling.append((m,i))
print("dangling AlgebraicJacobian imports:",len(dangling))
for d in dangling: print("   ",d)
# closure from root
seen=set()
stack=["AlgebraicJacobian"]
while stack:
    m=stack.pop()
    if m in seen or m not in files: continue
    seen.add(m)
    for i in imports[m]:
        if i in files and i not in seen: stack.append(i)
print("reachable from AlgebraicJacobian.lean:",len(seen))
un=sorted(set(files)-seen)
print("UNROOTED:",len(un))
for u in un: print("   ",u)
EOF
